const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('constructor', () => {
    it('starts with no items and no discount', () => {
      assert.deepEqual(cart.items, []);
      assert.equal(cart.discount, 0);
    });
  });

  describe('addItem', () => {
    it('adds a new line item with its name, price and quantity', () => {
      cart.addItem('apple', 1.5, 4);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 4 }]);
    });

    it('merges quantity into the existing line when the same name is added again', () => {
      cart.addItem('apple', 1.5, 2);
      cart.addItem('apple', 1.5, 3);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 5 }]);
    });

    it('keeps the original unit price when merging a repeated name', () => {
      cart.addItem('apple', 1.5, 1);
      cart.addItem('apple', 9.99, 1);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
    });

    it('defaults quantity to 1 when omitted', () => {
      cart.addItem('apple', 2);
      assert.equal(cart.items[0].quantity, 1);
    });

