const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

describe('ShoppingCart.updateQuantity', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
    cart.addItem('apple', 1.5, 2);
    cart.addItem('pear', 2, 1);
  });

  const snapshot = () => JSON.parse(JSON.stringify({ items: cart.items, discount: cart.discount }));

  it('sets the quantity of an existing item, up or down', () => {
    cart.updateQuantity('apple', 7);
    assert.equal(cart.items[0].quantity, 7);
    cart.updateQuantity('apple', 1);
    assert.equal(cart.items[0].quantity, 1);
  });

  it('keeps the unit price and the other lines', () => {
    cart.updateQuantity('apple', 5);
    assert.deepEqual(cart.items, [
      { name: 'apple', price: 1.5, quantity: 5 },
      { name: 'pear', price: 2, quantity: 1 },
    ]);
  });

  it('is reflected in getTotal and getItemCount', () => {
    cart.updateQuantity('apple', 4);
    assert.equal(cart.getTotal(), 4 * 1.5 + 2);
    assert.equal(cart.getItemCount(), 2);
  });

  it('removes the item when the quantity is 0', () => {
    cart.updateQuantity('apple', 0);
    assert.deepEqual(cart.items, [{ name: 'pear', price: 2, quantity: 1 }]);
    assert.equal(cart.getItemCount(), 1);
  });

  it('treats -0 as 0', () => {
    cart.updateQuantity('apple', -0);
    assert.equal(cart.getItemCount(), 1);
  });

  it('allows the item to be added again after removal', () => {
    cart.updateQuantity('apple', 0);
    cart.addItem('apple', 3, 2);
    assert.deepEqual(cart.items[1], { name: 'apple', price: 3, quantity: 2 });
  });

  it('accepts the same quantity as before', () => {
    cart.updateQuantity('apple', 2);
    assert.equal(cart.items[0].quantity, 2);
  });

  it('throws an Error for a missing item and leaves the cart unchanged', () => {
    const before = snapshot();
    assert.throws(() => cart.updateQuantity('banana', 3), Error);
    assert.throws(() => cart.updateQuantity('banana', 0), Error);
    assert.throws(() => cart.updateQuantity('Apple', 3), Error); // case-sensitive
    assert.deepEqual(snapshot(), before);
  });

  it('throws on any call against an empty cart', () => {
    assert.throws(() => new ShoppingCart().updateQuantity('apple', 1), Error);
  });

  const badQuantities = [
    ['negative', -1],
    ['negative zero-ish fraction', -0.5],
    ['fractional', 1.5],
    ['NaN', NaN],
    ['Infinity', Infinity],
    ['-Infinity', -Infinity],
    ['above MAX_SAFE_INTEGER', Number.MAX_SAFE_INTEGER + 1],
    ['numeric string', '3'],
    ['null', null],
    ['undefined', undefined],
    ['boolean', true],
    ['Symbol', Symbol('q')],
  ];

  for (const [label, value] of badQuantities) {
    it(`rejects a ${label} quantity and leaves the cart unchanged`, () => {
      const before = snapshot();
      assert.throws(() => cart.updateQuantity('apple', value), Error);
      assert.deepEqual(snapshot(), before);
    });
  }

  it('rejects a bad quantity for a missing item too', () => {
    assert.throws(() => cart.updateQuantity('banana', -1), Error);
  });

  it('rejects a non-string name and leaves the cart unchanged', () => {
    const before = snapshot();
    for (const name of [undefined, null, 1, {}, Symbol('n')]) {
      assert.throws(() => cart.updateQuantity(name, 1), TypeError);
    }
    assert.deepEqual(snapshot(), before);
  });

  it('does not touch the discount', () => {
    cart.applyDiscount(10);
    cart.updateQuantity('apple', 3);
    assert.equal(cart.discount, 10);
  });
});
